package vn.vplus.vremote.agent

import android.app.*
import android.content.*
import android.media.projection.MediaProjection
import android.os.*
import org.json.JSONObject
import org.webrtc.*
import okhttp3.*
import java.nio.charset.StandardCharsets
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.TimeUnit
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import kotlin.math.abs

class RemoteAgentService : Service() {
    private lateinit var socket: WebSocket; private lateinit var factory: PeerConnectionFactory; private lateinit var egl: EglBase
    private var peer: PeerConnection?=null; private var capturer: ScreenCapturerAndroid?=null; private var source: VideoSource?=null; private var activeSession:String?=null; private var projectionIntent:Intent?=null; private var expiryTask:Runnable?=null; @Volatile private var destroyed=false; private var polling=false; private var shownRequest:String?=null; private val notifId=2
    private val seenNonces=ConcurrentHashMap.newKeySet<String>(); private val processedCommands=ConcurrentHashMap.newKeySet<String>(); private val handler=Handler(Looper.getMainLooper())
    override fun onCreate(){super.onCreate();getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel(CHANNEL,"VRemote",NotificationManager.IMPORTANCE_LOW));startForeground(1,Notification.Builder(this,CHANNEL).setContentTitle("VRemote Agent").setContentText("Waiting for signed remote session").setSmallIcon(android.R.drawable.ic_menu_view).build());PeerConnectionFactory.initialize(PeerConnectionFactory.InitializationOptions.builder(this).createInitializationOptions());egl=EglBase.create();factory=PeerConnectionFactory.builder().setVideoEncoderFactory(DefaultVideoEncoderFactory(egl.eglBaseContext,true,true)).setVideoDecoderFactory(DefaultVideoDecoderFactory(egl.eglBaseContext)).createPeerConnectionFactory()}
    override fun onStartCommand(intent:Intent?,flags:Int,startId:Int):Int{
     if(intent?.action==ACTION_ACCEPT||intent?.action==ACTION_REJECT){respondPending(intent.getStringExtra(EXTRA_REQUEST_ID)?:"",intent.action==ACTION_ACCEPT);return START_STICKY}
     if(intent!=null&&intent.hasExtra(EXTRA_DATA))projectionIntent=intent.getParcelableExtraCompat(EXTRA_DATA)
     if(!::socket.isInitialized)connect()
     if(!polling){polling=true;startPendingPolling()}
     return START_STICKY}
    // Poll the backend for a pending connect the operator initiated; surface an accept/reject
    // notification (UltraViewer-style) that the user answers on the device.
    private fun startPendingPolling(){handler.postDelayed(object:Runnable{override fun run(){if(destroyed)return;pollPendingOnce();handler.postDelayed(this,2000)}},2000)}
    private fun pollPendingOnce(){val p=getSharedPreferences("vremote",MODE_PRIVATE);val base=p.getString("baseUrl","https://vremote.vplus.vn")?:"";val id=p.getString("deviceId","")?:"";val tok=p.getString("deviceToken","")?:"";if(id.isEmpty()||tok.isEmpty())return;Thread{try{val pend=ApiClient.pending(base,id,tok);handler.post{if(pend==null){if(shownRequest!=null){shownRequest=null;getSystemService(NotificationManager::class.java).cancel(notifId)}}else if(pend.requestId!=shownRequest){shownRequest=pend.requestId;showAcceptNotification(pend)}}}catch(_:Throwable){}}.start()}
    private fun showAcceptNotification(p:ApiClient.Pending){val f=PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE;val yes=PendingIntent.getService(this,1,Intent(this,RemoteAgentService::class.java).setAction(ACTION_ACCEPT).putExtra(EXTRA_REQUEST_ID,p.requestId),f);val no=PendingIntent.getService(this,2,Intent(this,RemoteAgentService::class.java).setAction(ACTION_REJECT).putExtra(EXTRA_REQUEST_ID,p.requestId),f);val n=Notification.Builder(this,CHANNEL).setContentTitle("Yêu cầu kết nối").setContentText("“${p.actor}” muốn xem màn hình.").setSmallIcon(android.R.drawable.ic_menu_view).addAction(android.R.drawable.ic_menu_view,"Đồng ý",yes).addAction(android.R.drawable.ic_menu_close_clear_cancel,"Từ chối",no).setAutoCancel(true).build();getSystemService(NotificationManager::class.java).notify(notifId,n)}
    private fun respondPending(rid:String,accept:Boolean){shownRequest=null;getSystemService(NotificationManager::class.java).cancel(notifId);if(rid.isEmpty())return;val p=getSharedPreferences("vremote",MODE_PRIVATE);val base=p.getString("baseUrl","https://vremote.vplus.vn")?:"";val id=p.getString("deviceId","")?:"";val tok=p.getString("deviceToken","")?:"";Thread{try{ApiClient.respond(base,id,tok,rid,accept)}catch(_:Throwable){}}.start()}
    private fun connect(){val p=getSharedPreferences("vremote",MODE_PRIVATE);val id=p.getString("deviceId","")?:"";val token=p.getString("deviceToken","")?:"";val url=p.getString("signalingUrl","ws://10.0.2.2:8787/agent")?:"";socket=OkHttpClient.Builder().pingInterval(20,TimeUnit.SECONDS).build().newWebSocket(Request.Builder().url(url).build(),object:WebSocketListener(){override fun onOpen(w:WebSocket,r:Response){w.send(JSONObject().put("type","agent.auth").put("deviceId",id).put("deviceToken",token).toString());w.send(JSONObject().put("type","agent.hello").put("deviceId",id).put("agentVersion",BuildConfig.VERSION_NAME).put("platform","android").put("capabilities",listOf("screen.view")).toString())};override fun onMessage(w:WebSocket,text:String){try{handle(JSONObject(text))}catch(_:Throwable){}};override fun onFailure(w:WebSocket,t:Throwable,r:Response?){handler.postDelayed({if(!destroyed)try{connect()}catch(_:Throwable){}},5000)}})}
    private fun handle(m:JSONObject){when(m.optString("type")){"session.enable"->enable(m);"session.disable"->disable(m);"command"->command(m);"offer"->handleOffer(m);"candidate"->handleCandidate(m)}}
    private fun enable(m:JSONObject){val p=getSharedPreferences("vremote",MODE_PRIVATE);val id=p.getString("deviceId","")?:"";val secret=p.getString("deviceToken","")?:"";val sid=m.optString("sessionId");val nonce=m.optString("nonce");val ts=m.optLong("ts",0);val ttl=m.optInt("ttlSec",0);val cap=m.optString("capability");val sig=m.optString("sig");if(m.optString("deviceId")!=id||sid.isBlank()||nonce.isBlank()||sig.isBlank()||ttl !in 1..3600||abs(System.currentTimeMillis()/1000-ts)>300)return;if(!VRemoteSigner.verify(secret,VRemoteSigner.canonicalSessionEnable(id,sid,cap,ttl,nonce,ts),sig))return;if(!seenNonces.add("session:$nonce"))return;disableCurrent();p.edit().putInt("lastSessionTtl",ttl).putLong("lastSessionExpires",ts+ttl).apply();activeSession=sid;expiryTask=Runnable{if(activeSession==sid)disableCurrent()};handler.postDelayed(expiryTask!!,ttl*1000L);if(!startCapture())return;sendSignal(JSONObject().put("type","agent.signaling").put("sessionId",sid).put("payload",JSONObject().put("type","ready").put("sessionId",sid)))}
    private fun startCapture():Boolean{if(peer!=null)return true;val data=projectionIntent?:return false;val p=getSharedPreferences("vremote",MODE_PRIVATE);val servers=mutableListOf<PeerConnection.IceServer>();servers.add(PeerConnection.IceServer.builder("stun:stun.l.google.com:19302").createIceServer());val turnUrl=p.getString("turnUrl","")?:"";val turnSecret=p.getString("turnSecret","")?:"";val id=p.getString("deviceId","")?:"";if(turnUrl.isNotBlank()&&turnSecret.isNotBlank()){val expires=p.getLong("lastSessionExpires",System.currentTimeMillis()/1000+1800);val username=expires.toString()+":"+id;servers.add(PeerConnection.IceServer.builder(turnUrl).setUsername(username).setPassword(turnCredential(turnSecret,username)).createIceServer())};peer=factory.createPeerConnection(servers,observer())?:return false;val capt=ScreenCapturerAndroid(data,object:MediaProjection.Callback(){override fun onStop(){disableCurrent()}});capturer=capt;source=factory.createVideoSource(true);val helper=SurfaceTextureHelper.create("VRemoteCapture",egl.eglBaseContext);capt.initialize(helper,this,source!!.capturerObserver);capt.startCapture(1280,720,15);peer!!.addTrack(factory.createVideoTrack("screen",source!!),listOf("screen"));return true}
    private fun turnCredential(secret:String,username:String):String{val mac=Mac.getInstance("HmacSHA1");mac.init(SecretKeySpec(secret.toByteArray(StandardCharsets.UTF_8),"HmacSHA1"));return Base64.getEncoder().encodeToString(mac.doFinal(username.toByteArray(StandardCharsets.UTF_8)))}
    private fun observer()=object:PeerConnection.Observer{override fun onIceCandidate(c:IceCandidate){sendSignal(JSONObject().put("type","agent.signaling").put("sessionId",activeSession).put("payload",JSONObject().put("type","candidate").put("sessionId",activeSession).put("candidate",JSONObject().put("sdpMid",c.sdpMid).put("sdpMLineIndex",c.sdpMLineIndex).put("candidate",c.sdp))))};override fun onSignalingChange(s:PeerConnection.SignalingState){};override fun onIceConnectionChange(s:PeerConnection.IceConnectionState){};override fun onIceConnectionReceivingChange(b:Boolean){};override fun onIceGatheringChange(s:PeerConnection.IceGatheringState){};override fun onIceCandidatesRemoved(c:Array<IceCandidate>){};override fun onAddStream(s:MediaStream){};override fun onRemoveStream(s:MediaStream){};override fun onDataChannel(d:DataChannel){};override fun onRenegotiationNeeded(){};override fun onAddTrack(r:RtpReceiver,m:Array<MediaStream>){};override fun onConnectionChange(s:PeerConnection.PeerConnectionState){};override fun onSelectedCandidatePairChanged(e:CandidatePairChangeEvent){}}
    private fun handleOffer(m:JSONObject){val sdp=m.optString("sdp");if(sdp.isBlank()||peer==null)return;peer!!.setRemoteDescription(SimpleSdpObserver(),SessionDescription(SessionDescription.Type.OFFER,sdp));peer!!.createAnswer(object:SimpleSdpObserver(){override fun onCreateSuccess(d:SessionDescription){peer?.setLocalDescription(SimpleSdpObserver(),d);sendSignal(JSONObject().put("type","agent.signaling").put("sessionId",activeSession).put("payload",JSONObject().put("type","answer").put("sessionId",activeSession).put("sdp",d.description)))}},MediaConstraints())}
    private fun handleCandidate(m:JSONObject){val c=m.optJSONObject("candidate")?:return;peer?.addIceCandidate(IceCandidate(c.optString("sdpMid"),c.optInt("sdpMLineIndex"),c.optString("candidate")))}
    private fun command(m:JSONObject){val p=getSharedPreferences("vremote",MODE_PRIVATE);val id=p.getString("deviceId","")?:"";val secret=p.getString("deviceToken","")?:"";val cid=m.optString("commandId");val type=m.optString("cmdType");val nonce=m.optString("nonce");val ts=m.optLong("ts",0);val sig=m.optString("sig");if(m.optString("deviceId")!=id||cid.isBlank()||nonce.isBlank()||sig.isBlank()||abs(System.currentTimeMillis()/1000-ts)>300){commandResult(cid,"rejected","stale_or_invalid");return};val args=m.optJSONObject("args");val argsJson=args?.toString();if(!VRemoteSigner.verify(secret,VRemoteSigner.canonicalCommand(id,cid,type,VRemoteSigner.argsHash(argsJson),nonce,ts),sig)){commandResult(cid,"invalid_signature",null);return};if(!seenNonces.add("cmd:$nonce")){commandResult(cid,"replay_detected",null);return};if(!processedCommands.add(cid)){commandResult(cid,"done",null);return};val gated=setOf("reboot","config-push","apk-update","cache-clear","remote.enable","remote.disable");if(type in gated&&!p.getBoolean("allowGatedCommands",false)){commandResult(cid,"gated_off",null);return};when(type){"health","ping"->commandResult(cid,"done",mapOf("online" to true,"activeSession" to activeSession));"version"->commandResult(cid,"done",mapOf("agentVersion" to BuildConfig.VERSION_NAME,"versionCode" to BuildConfig.VERSION_CODE));"logs","config-read"->commandResult(cid,"done",emptyMap<String,String>());"apk-update"->{val base=p.getString("baseUrl","https://vremote.vplus.vn")?:"";Thread{try{val info=ApiClient.latest(base);if(info.versionCode<=BuildConfig.VERSION_CODE)commandResult(cid,"done",mapOf("updated" to false,"installed" to BuildConfig.VERSION_NAME)) else if(!AgentUpdater.canInstall(this))commandResult(cid,"error","install_permission_required") else{AgentUpdater.install(this,AgentUpdater.download(this,base,info));commandResult(cid,"done",mapOf("updated" to true,"downloaded" to info.versionName))}}catch(e:Throwable){commandResult(cid,"error",e.message?:"update_failed")}}.start()};else->commandResult(cid,"error","unsupported_command")}}
    private fun commandResult(id:String,result:String,data:Any?){if(id.isBlank())return;val d=JSONObject();when(data){is Map<*,*>->data.forEach{(k,v)->d.put(k.toString(),v)};is String->d.put("detail",data)};sendSignal(JSONObject().put("type","command.result").put("deviceId",getSharedPreferences("vremote",MODE_PRIVATE).getString("deviceId","")).put("commandId",id).put("result",result).put("data",if(d.length()>0)d else JSONObject.NULL))}
    private fun sendSignal(p:JSONObject){if(::socket.isInitialized)socket.send(p.toString())};private fun disable(m:JSONObject){if(m.optString("sessionId")==activeSession)disableCurrent()};private fun disableCurrent(){expiryTask?.let{handler.removeCallbacks(it)};try{capturer?.stopCapture()}catch(_:Throwable){};capturer?.dispose();capturer=null;peer?.close();peer=null;source?.dispose();source=null;activeSession=null}
    override fun onBind(i:Intent?):IBinder?=null;override fun onDestroy(){destroyed=true;disableCurrent();try{socket.close(1000,"shutdown")}catch(_:Throwable){};factory.dispose();egl.release();super.onDestroy()}
    companion object{const val EXTRA_RESULT_CODE="resultCode";const val EXTRA_DATA="projectionData";private const val CHANNEL="vremote-agent";const val ACTION_ACCEPT="vn.vplus.vremote.ACCEPT";const val ACTION_REJECT="vn.vplus.vremote.REJECT";const val EXTRA_REQUEST_ID="requestId"}
}
private open class SimpleSdpObserver:SdpObserver{override fun onCreateSuccess(s:SessionDescription){};override fun onSetSuccess(){};override fun onCreateFailure(s:String){};override fun onSetFailure(s:String){}}
private fun Intent.getParcelableExtraCompat(key:String):Intent?=if(Build.VERSION.SDK_INT>=33)getParcelableExtra(key,Intent::class.java)else @Suppress("DEPRECATION") getParcelableExtra(key)
